JS=r'''
(()=>{'use strict';
 const DATA=__DATA__,STEP=6,DURATION=24,TOTAL=DATA.length*DURATION,KEY='android-animated-slides-player-v1';
 const $=id=>document.getElementById(id),player=$('player'),stage=$('stage'),controls=$('controls'),range=$('timeline'),playButton=$('play'),select=$('chapters');
 let elapsed=0,rate=1,playing=false,raf=0,last=0,lastPaint=0,index=-1,step=-1,wasPlaying=false,touch=null;
 let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(_){}
 if(Number.isInteger(saved.slide)&&saved.slide>=0&&saved.slide<DATA.length)elapsed=saved.slide*DURATION;
 if([.75,1,1.25,1.5,2].includes(saved.rate))rate=saved.rate;
 const hash=location.hash.match(/^#slide-(\d+)$/);if(hash){const n=Number(hash[1])-1;if(n>=0&&n<DATA.length)elapsed=n*DURATION}
 function persist(){try{localStorage.setItem(KEY,JSON.stringify({slide:Math.min(DATA.length-1,Math.floor(elapsed/DURATION)),rate}))}catch(_){}}
 function message(text){$('status').textContent=text}
 function time(value){value=Math.floor(value);return String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0')}
 function transport(){playButton.textContent=playing?'一時停止':elapsed>=TOTAL?'最初から再生':'再生';playButton.setAttribute('aria-label',playing?'一時停止':'スライドを再生');playButton.setAttribute('aria-pressed',String(playing));player.classList.toggle('playing',playing);opening()}
 function pause(announce=false){settleCuts();playing=false;cancelAnimationFrame(raf);raf=0;last=0;transport();persist();if(announce)message('一時停止しました。')}
 function play(){if(playing)return;dismissOpening();if(elapsed>=TOTAL)elapsed=0;playing=true;last=0;render();transport();message('再生しています。音声はありません。');raf=requestAnimationFrame(tick)}
 function tick(now){if(!playing)return;if(last)elapsed=Math.min(TOTAL,elapsed+Math.min((now-last)/1000,.25)*rate);last=now;render(now);if(elapsed>=TOTAL){pause();message('最後まで再生しました。元の教材で理解を深められます。');return}raf=requestAnimationFrame(tick)}
 function seek(value,manual=true){if(manual){pause();dismissOpening()}elapsed=Math.max(0,Math.min(TOTAL,Number(value)||0));render();persist()}
 function jump(n){seek(Math.max(0,Math.min(DATA.length-1,n))*DURATION);message('スライド '+(index+1)+' を表示しました。')}
 function render(now=0){const n=Math.min(DATA.length-1,Math.floor(elapsed/DURATION)),s=Math.min(3,Math.floor((elapsed>=TOTAL?DURATION-.001:elapsed-n*DURATION)/STEP));const slide=DATA[n];if(n===index&&s===step&&now&&now-lastPaint<200&&elapsed<TOTAL)return;
  if(n!==index){const hadSlide=index>=0;index=n;step=-1;select.value=String(n);$('slide-title').textContent=slide.direction.hook;$('slide-tag').textContent='MODULE '+slide.module.index+' / '+slide.module.name;$('slide-number').textContent=String(n+1).padStart(2,'0')+' / '+DATA.length;$('note-title').textContent=slide.title;$('note').textContent=slide.note;$('question').textContent=slide.question;$('answer').textContent=slide.answer;$('quiz').open=false;$('reference').href='../guide/index.html#'+slide.chapter;
   $('explanation').replaceChildren(...slide.steps.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));$('diagram').innerHTML=slide.svg;$('diagram').dataset.kind=slide.diagramType;$('diagram').setAttribute('aria-label',slide.diagramLabel+'。'+slide.nodes.map((name,i)=>(i+1)+' '+name).join('、'));$('flow-label').textContent=slide.diagramLabel;prepareCase(slide);if(hadSlide)animateOnce($('scene-body'));try{history.replaceState(null,'','#slide-'+(n+1))}catch(_){}persist();
  }
  if(s!==step){step=s;$('diagram').querySelectorAll('[data-step]').forEach(node=>node.classList.toggle('focus',Number(node.dataset.step)===s));$('cue').textContent=slide.steps[s];$('cue-label').textContent='説明 '+(s+1)+' / 4';[...$('explanation').children].forEach((li,i)=>li.classList.toggle('current',i===s));$('steps').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===s)));directCase(slide,s);}
  if(!now||now-lastPaint>200||elapsed>=TOTAL){range.value=String(elapsed);range.setAttribute('aria-valuetext','スライド'+(n+1)+'、'+time(elapsed));$('time').textContent=time(elapsed)+' / '+time(TOTAL);lastPaint=now;}
  stage.style.setProperty('--beat-progress',String(elapsed>=TOTAL?1:(elapsed%STEP)/STEP));opening();
  if($('prev').disabled!==(n===0))$('prev').disabled=n===0;if($('next').disabled!==(n===DATA.length-1))$('next').disabled=n===DATA.length-1;
 }
 function isFull(){return !!document.fullscreenElement||document.body.classList.contains('immersive')}
 function layout(){stage.style.removeProperty('width');stage.classList.toggle('compact',stage.clientWidth<360);if(isFull()){const h=Math.ceil(controls.getBoundingClientRect().height);if(player.style.getPropertyValue('--controls-height')!==h+'px')player.style.setProperty('--controls-height',h+'px')}}
 function fullState(){const full=isFull();$('fullscreen').textContent=full?'全画面を終了':'全画面';$('fullscreen').setAttribute('aria-pressed',String(full));syncCinema(full);layout();if(!full){try{screen.orientation?.unlock?.()}catch(_){}}}
 async function fullscreen(){if(isFull()){if(document.fullscreenElement){try{await document.exitFullscreen()}catch(_){}}document.body.classList.remove('immersive');fullState();$('fullscreen').focus();return}
  let native=false;try{if(player.requestFullscreen){await player.requestFullscreen();native=!!document.fullscreenElement}}catch(_){}
  if(!native){document.body.classList.add('immersive');message('ブラウザ内の全画面表示です。終了ボタンかEscapeで戻れます。')}
  fullState();if(native){try{await screen.orientation?.lock?.('landscape')}catch(_){}}
 }
 playButton.addEventListener('click',()=>playing?pause(true):play());$('prev').addEventListener('click',()=>jump(index-1));$('next').addEventListener('click',()=>jump(index+1));select.addEventListener('change',()=>jump(Number(select.value)));$('speed').value=String(rate);$('speed').addEventListener('change',e=>{rate=Number(e.target.value);player.style.setProperty('--packet-duration',(2.4/rate)+'s');player.style.setProperty('--demo-duration',(2/rate)+'s');persist()});$('fullscreen').addEventListener('click',fullscreen);
 range.addEventListener('pointerdown',()=>{wasPlaying=playing;pause()});range.addEventListener('input',()=>seek(range.value));range.addEventListener('pointerup',()=>{if(wasPlaying)play();wasPlaying=false});range.addEventListener('pointercancel',()=>{wasPlaying=false});
 $('steps').addEventListener('click',e=>{const b=e.target.closest('button[data-step]');if(b)seek(index*DURATION+Number(b.dataset.step)*STEP)});$('quiz').addEventListener('toggle',()=>{if($('quiz').open)pause()});
 stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){if(!e.isPrimary){touch=null;return}touch={x:e.clientX,y:e.clientY}}});stage.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.5){jump(index+(dx<0?1:-1));stage.dataset.swiped='1';setTimeout(()=>delete stage.dataset.swiped,250)}});stage.addEventListener('click',e=>{if(e.target.closest('button')||stage.dataset.swiped)return;if(isFull()){player.classList.contains('controls-open')?hideChrome(true):showChrome();return}playing?pause(true):play()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('immersive')){document.body.classList.remove('immersive');fullState();$('fullscreen').focus();return}if(e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,select,button,a,summary,textarea'))return;let handled=true;switch(e.key){case ' ':playing?pause(true):play();break;case 'ArrowRight':seek(Math.min(TOTAL,(Math.floor(elapsed/STEP)+1)*STEP));break;case 'ArrowLeft':seek(Math.max(0,(Math.ceil(elapsed/STEP)-1)*STEP));break;case 'PageDown':jump(index+1);break;case 'PageUp':jump(index-1);break;case 'Home':jump(0);break;case 'End':jump(DATA.length-1);break;case 'f':case 'F':fullscreen();break;default:handled=false}if(handled)e.preventDefault()});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){pause();message('別の画面へ移ったため、一時停止しました。')}});window.addEventListener('hashchange',()=>{const h=location.hash.match(/^#slide-(\d+)$/);if(h){const n=Number(h[1])-1;if(n>=0&&n<DATA.length&&n!==index)jump(n)}});document.addEventListener('fullscreenchange',fullState);window.addEventListener('resize',layout);if(window.ResizeObserver){const observer=new ResizeObserver(layout);observer.observe(player);observer.observe(controls)}window.addEventListener('pagehide',()=>{pause();persist()});
__DIRECTION_JS__
__FULLSCREEN_JS__
 DATA.forEach((slide,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=String(i+1).padStart(2,'0')+' / '+slide.title;select.append(o)});range.max=String(TOTAL);player.style.setProperty('--packet-duration',(2.4/rate)+'s');player.style.setProperty('--demo-duration',(2/rate)+'s');document.documentElement.classList.add('scripted');document.querySelector('.skip').href='#player';render();transport();layout();message('再生を選ぶと、図と説明が順に進みます。');
})();
'''
TEMPLATE='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="description" content="Android 16の30章を動く図と字幕で振り返る、16:9のスライド教材。全32枚、自動再生とスマートフォン全画面に対応。"><title>Androidを動く図で学ぶ｜スライド教材</title><style>__CSS__</style></head><body><a class="skip" href="#all-slides">スライド教材へ移動</a><header class="header wrap"><a href="../index.html">← Androidの教材一覧</a><a href="../guide/index.html">元のAndroid教材を読む ↗</a></header><main class="wrap"><section class="intro"><div><p class="eyebrow">ANDROID 16 / MOTION LESSONS</p><h1>Androidを、<br>動く図で学ぶ。</h1></div><p>身近な疑問から、図と実例で仕組みを追う32レッスン。<br>16:9・字幕付き・音声なし。標準速度で約13分。<br>停止して図を見返し、本文へ進めます。</p></section><nav class="chapters-strip" id="module-nav" aria-label="学習モジュールを選ぶ"></nav><noscript><p class="noscript-note">JavaScriptが無効のため、下に静止版の全スライドを表示しています。</p></noscript><section class="player" id="player" tabindex="-1" aria-label="Androidスライドプレーヤー"><div class="screen-wrap"><section class="stage" id="stage" tabindex="0" aria-labelledby="slide-title" aria-describedby="cue"><div class="slide-heading"><div><p class="slide-tag" id="slide-tag"></p><h2 id="slide-title"></h2></div><span class="slide-number" id="slide-number"></span></div><div class="scene-body" id="scene-body"><div class="diagram" id="diagram" role="img"></div>__CASE_HTML__</div><div class="cue-box"><p class="cue-label" id="cue-label"></p><p class="cue" id="cue"></p><span class="beat-progress" aria-hidden="true"></span></div><div class="slide-foot"><span class="flow-label" id="flow-label"></span><button class="view-case" id="view-case" type="button" aria-pressed="false" aria-label="説明用の実例を拡大する">実例</button><div class="steps" id="steps" aria-label="説明の位置">__STEP_BUTTONS__</div></div>__OPENING__</section></div><p class="portrait-hint" id="portrait-hint">横向きにすると、スライドを大きく表示できます。</p><div class="controls" id="controls"><p class="cinema-help">画面のタップ・マウス移動・Tabで操作を表示。Spaceで再生／停止、Escapeで全画面を終了。</p><div class="timeline"><label class="sr-only" for="timeline">教材全体の再生位置</label><input id="timeline" type="range" min="0" step="0.1" value="0"><span class="time" id="time"></span></div><div class="button-row"><button id="prev" type="button" aria-label="前のスライド">前へ</button><button id="play" class="play" type="button" aria-pressed="false">再生</button><button id="next" type="button" aria-label="次のスライド">次へ</button><label class="chapter-picker"><span class="sr-only">スライドを選ぶ</span><select id="chapters" aria-label="スライドを選ぶ"></select></label><label class="speed">速度<select id="speed" aria-label="再生速度"><option value="0.75">0.75倍</option><option value="1">1倍</option><option value="1.25">1.25倍</option><option value="1.5">1.5倍</option><option value="2">2倍</option></select></label><button id="hide-controls" class="hide-controls" type="button">操作を隠す</button><button id="fullscreen" class="full" type="button" aria-pressed="false">全画面</button></div></div></section><p class="status" id="status" role="status" aria-live="polite"></p><p class="help">図の番号は説明の段階に対応します。矢印と図中のラベルで、要求・応答・観測などを区別します。通常表示では図をタップして再生・停止。全画面ではタップ・マウス移動・Tabで操作バーを表示し、操作がなければ隠れます。左右スワイプで前後のスライドへ。図にフォーカスした状態で、Space：再生・停止、← →：説明単位の移動、Home / End：最初・最後、F：全画面。全画面が使えないブラウザでは画面内を最大化します。</p><section class="transcript" aria-labelledby="note-title"><h2 id="note-title">スライドの解説</h2><p class="note" id="note"></p><ol id="explanation"></ol>__RECAP__<details id="quiz"><summary>理解を確かめる：<span id="question"></span></summary><p id="answer"></p></details><div class="text-links"><a id="reference" href="../guide/index.html">この内容を元の教材で読む →</a><a href="../index.html">Androidの教材一覧へ戻る</a></div></section><section class="fallback" id="all-slides" aria-label="全スライドの静止版">__FALLBACK__</section></main><footer class="footer wrap"><a href="../index.html">← Androidの教材一覧</a><span>Android 16 / 図は説明用に簡略化しています</span></footer><script>__JS__</script></body></html>'''
def build():
    source=(ROOT/'android/guide/index.html').read_text()
    for slide in SLIDES:
        assert 'id="'+slide['chapter']+'"' in source,slide['chapter']
        drawing=ElementTree.fromstring(slide['svg'])
        assert {int(el.attrib['data-step']) for el in drawing.iter() if 'data-step' in el.attrib}=={0,1,2,3},slide['chapter']
    fallback=[]
    for i,s in enumerate(SLIDES):
        flow,label=diagram(s,static=True)
        direction=s['direction']
        case_steps=''.join('<li><b>'+html.escape(f['status']+'：'+f['value'])+'</b> — '+html.escape(f['detail'])+'</li>' for f in direction['frames'])
        steps=''.join('<li>'+html.escape(t)+'</li>' for t in s['steps'])
        fallback.append(f'<article id="static-slide-{i+1}"><p class="eyebrow">SLIDE {i+1} / {len(SLIDES)}</p><h2>{html.escape(s["title"])}</h2><p class="case-hook">{html.escape(direction["hook"])}</p><div class="static-diagram" role="img" aria-label="{html.escape(label+"。"+"、".join(s["nodes"]),quote=True)}">{flow}</div><ol>{steps}</ol><p>{html.escape(s["note"])}</p><section class="case-notes"><h3>説明用の実例：{html.escape(direction["label"])}</h3><ol>{case_steps}</ol></section><p class="lesson-conclusion">要点：{html.escape(direction["takeaway"])}</p><p><strong>確認問題：</strong>{html.escape(s["question"])}</p><p class="answer"><strong>解答：</strong>{html.escape(s["answer"])}</p><a href="../guide/index.html#{s["chapter"]}">元の教材で読む</a></article>')
    buttons=''.join(f'<button type="button" data-step="{i}" aria-label="説明{i+1}へ移動" aria-pressed="false">{i+1}</button>' for i in range(4))
    data=json.dumps(SLIDES,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    directed_js=JS.replace('__FULLSCREEN_JS__',FULLSCREEN_JS).replace('__DIRECTION_JS__',DIRECTION_JS.replace('__MODULES__',json.dumps(MODULES,ensure_ascii=False))).replace('__DATA__',data)
    result=TEMPLATE.replace('__CSS__',CSS).replace('__FALLBACK__','\n'.join(fallback)).replace('__STEP_BUTTONS__',buttons).replace('__JS__',directed_js).replace('__CASE_HTML__',CASE_HTML).replace('__OPENING__',OPENING).replace('__RECAP__',RECAP)
    target=ROOT/'android/slides/index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(result)
    print(f'Verified {len(SLIDES)} slides / {len(SLIDES)*4} explanations and original chapter links; {len(result.encode()):,} bytes.')
if __name__=='__main__':build()
